import json, html, re
from pathlib import Path
from decimal import Decimal, ROUND_HALF_UP

ROOT = Path(__file__).resolve().parents[1]
PAGES = json.loads((ROOT/'research/retrieved-pages.json').read_text())
RUBRIC = json.loads((ROOT/'research/rubric.json').read_text())
QUERIES = json.loads((ROOT/'research/visibility-sample.json').read_text())
DATE = 'September 10, 2026'
E = html.escape
def R(value): return float(Decimal(str(value)).quantize(Decimal('0.1'), rounding=ROUND_HALF_UP))

def link(url, label):
    assert url.startswith(('https://','http://'))
    return f'<a href="{E(url, quote=True)}" target="_blank" rel="noopener noreferrer">{E(label)}</a>'

