    gallery_label='Landing Love entry and recording' if 'landing.love' in gallery else 'Design case study' if 'unseen.co' in gallery else 'Gallery entry'
    return f'<article class="reference"><div class="ref-num">{num}</div><div><h3>{E(name)}</h3><p class="eyebrow">{E(geo)}</p><p>{E(composition)}</p><p><b>Animation and effect.</b> {E(motion)}</p><p><b>What to borrow.</b> {E(adapt)}</p><p class="source-links">{link(url,"Live website")} · {link(gallery,gallery_label)} · {link(shot,"External reference image")}</p></div></article>'

